arguments.file_text:
namespace sv_aa207cb17349483495cfa1173a395e8c.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@using sv_aa207cb17349483495cfa1173a395e8c.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    @* ─── Left Sidebar: Channel List ─── *@
    <aside class="channel-sidebar">
        <h4 class="sidebar-title">Channels</h4>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-header-row">
                            <span class="channel-name"># @channel.Name</span>
                            @if (channel.UnreadCount > 0)
                            {
                                <span class="unread-badge">@channel.UnreadCount</span>
                            }
                        </div>
                        @if (!string.IsNullOrWhiteSpace(channel.Description))
                        {
                            <span class="channel-desc">@TruncateDescription(channel.Description)</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ─── Main Message Area ─── *@
    <section class="message-area @(_threadOpen ? "thread-open" : "thread-closed")">
        @if (_activeChannel is not null)
        {
            <div class="message-area-header">
                <h5 class="current-channel-name"># @_activeChannel.Name</h5>
                <p class="current-channel-desc">@_activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScrollAsync">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-card" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-meta">
                                <span class="message-author">@msg.Author</span>
                                <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>

                            @* Reactions *@
                            @if (msg.Reactions?.Count > 0)
                            {
                                <div class="reactions-row">
                                    @foreach (var reaction in msg.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ToggleReactionAsync(msg.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }

                            @* Thread starter indicator *@
                            @if (_threadSummaries.TryGetValue(msg.Id, out var summary))
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                    @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                    &middot; Last @FormatRelativeTime(summary.LastReplyAt)
                                </button>
                            }

                            @* Hover action buttons *@
                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg.Id)">
                                        💬 Reply
                                    </button>
                                    <button class="action-btn" title="Add reaction"
                                            @onclick="() => ToggleEmojiPicker(msg.Id)">
                                        😀 React
                                    </button>
                                </div>

                                @if (_emojiPickerMessageId == msg.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-option"
                                                    @onclick="() => AddEmojiReactionAsync(msg.Id, emoji)">
                                                @emoji
                                            </button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            @* Message Input *@
            <div class="message-input-area">
                <textarea class="message-textarea" rows="2" placeholder="Type a message…"
                          @bind="_newMessageContent" @bind:event="oninput"
                          @onkeydown="OnMessageKeyDownAsync" />
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageContent)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ─── Right Panel: Thread View ─── *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h5>Thread</h5>
                <button class="close-thread-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>

            <div class="thread-root-quote">
                <span class="thread-root-author">@_threadRootMessage.Author</span>
                <p class="thread-root-content">@_threadRootMessage.Content</p>
            </div>

            <div class="thread-messages">
                @if (_threadReplies is not null)
                {
                    @foreach (var reply in _threadReplies)
                    {
                        <div class="message-card thread-reply">
                            <div class="message-meta">
                                <span class="message-author">@reply.Author</span>
                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>

                            @if (reply.Reactions?.Count > 0)
                            {
                                <div class="reactions-row">
                                    @foreach (var reaction in reply.Reactions)
                                    {
                                        <button class="reaction-badge"
                                                title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ToggleReactionAsync(reply.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-textarea" rows="2" placeholder="Reply in thread…"
                          @bind="_threadReplyContent" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDownAsync" />
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReplyContent)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;

    private List<Message>? _messages;
    private int _messagesSkip;
    private bool _loadingOlder;
    private bool _hasMoreOlderMessages = true;

    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "👀", "🚀"];

    private string _newMessageContent = string.Empty;

    // Thread panel state
    private bool _threadOpen;
    private int? _threadRootMessageId;
    private Message? _threadRootMessage;
    private List<Message>? _threadReplies;
    private string _threadReplyContent = string.Empty;

    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels?.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (_activeChannelId == channel.Id) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messagesSkip = 0;
        _hasMoreOlderMessages = true;
        _messages = new List<Message>();

        CloseThread();

        var fetched = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = fetched;
        _messagesSkip = fetched.Count;
        _hasMoreOlderMessages = fetched.Count == PageSize;

        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channel.Id);
        RefreshChannelUnread(channel.Id);

        await ScrollToBottomAsync();
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_loadingOlder || !_hasMoreOlderMessages || _activeChannelId is null) return;

        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messagesSkip, PageSize);
        if (older.Count > 0)
        {
            _messages!.InsertRange(0, older);
            _messagesSkip += older.Count;
            BuildThreadSummaries();
        }
        _hasMoreOlderMessages = older.Count == PageSize;
        _loadingOlder = false;
    }

    private async Task OnMessageListScrollAsync()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop <= 1)
        {
            await LoadOlderMessagesAsync();
        }
    }

    private void BuildThreadSummaries()
    {
        if (_messages is null) return;

        var rootIds = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => new ThreadSummary(
                g.Key,
                g.Count(),
                g.Max(m => m.SentAt)
            ));

        // Also keep any existing summaries for root messages that have replies loaded in the thread panel
        foreach (var kvp in rootIds)
        {
            _threadSummaries[kvp.Key] = kvp.Value;
        }
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageContent) || _activeChannelId is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageContent.Trim(), null);
        _messages!.Add(sent);
        _messagesSkip++;
        _newMessageContent = string.Empty;

        await ScrollToBottomAsync();
    }

    private async Task OnMessageKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OnThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootMessageId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadReplyContent = string.Empty;
        _emojiPickerMessageId = null;

        var allThreadMessages = await ChatService.GetThreadAsync(rootMessageId);
        // The service returns the root + replies; separate them
        _threadReplies = allThreadMessages.Where(m => m.Id != rootMessageId).ToList();
        _threadRootMessage ??= allThreadMessages.FirstOrDefault(m => m.Id == rootMessageId);

        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessageId = null;
        _threadRootMessage = null;
        _threadReplies = null;
        _threadReplyContent = string.Empty;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyContent) || _activeChannelId is null || _threadRootMessageId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyContent.Trim(), _threadRootMessageId);
        _threadReplies!.Add(reply);
        _threadReplyContent = string.Empty;

        // Update thread summary in the main message list
        var replyCount = _threadReplies.Count;
        _threadSummaries[_threadRootMessageId.Value] = new ThreadSummary(
            _threadRootMessageId.Value, replyCount, reply.SentAt);
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddEmojiReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;
        await RefreshMessageReactionsAsync(messageId);
    }

    private async Task ToggleReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        await RefreshMessageReactionsAsync(messageId);
    }

    private async Task RefreshMessageReactionsAsync(int messageId)
    {
        // Re-fetch the channel messages to update reactions in-place
        if (_activeChannelId is null) return;

        // Check main message list
        var idx = _messages?.FindIndex(m => m.Id == messageId) ?? -1;
        if (idx >= 0)
        {
            var updated = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messagesSkip);
            var refreshed = updated.FirstOrDefault(m => m.Id == messageId);
            if (refreshed is not null && _messages is not null)
            {
                _messages[idx] = refreshed;
            }
        }

        // Check thread replies
        if (_threadReplies is not null)
        {
            var tidx = _threadReplies.FindIndex(m => m.Id == messageId);
            if (tidx >= 0 && _threadRootMessageId is not null)
            {
                var threadMsgs = await ChatService.GetThreadAsync(_threadRootMessageId.Value);
                var refreshed = threadMsgs.FirstOrDefault(m => m.Id == messageId);
                if (refreshed is not null)
                {
                    _threadReplies[tidx] = refreshed;
                }
            }
        }
    }

    private void RefreshChannelUnread(int channelId)
    {
        if (_channels is null) return;
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task ScrollToBottomAsync()
    {
        await Task.Yield();
        try
        {
            await JS.InvokeVoidAsync("eval",
                "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
        }
        catch { /* Component may not be rendered yet */ }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string desc) =>
        desc.Length > 40 ? desc[..37] + "…" : desc;
}

